// components/pages/Customer360.js - Complete working version
import React, { useState } from 'react';
import { apiCall, normalizePhone, escapeHtml } from '../../utils/api';

const Customer360 = ({ showToast }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchType, setSearchType] = useState('all');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [customerDetail, setCustomerDetail] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSearch = async () => {
    if (!searchTerm.trim()) {
      setSearchResults([]);
      setCustomerDetail(null);
      return;
    }

    setLoading(true);
    try {
      const linesResult = await apiCall('getLines');
      const lines = linesResult.lines || [];

      if (lines.length === 0) {
        setSearchResults([]);
        setLoading(false);
        showToast('No customers found. Please register some lines first.', true);
        return;
      }

      const term = searchTerm.toLowerCase().trim();
      let customers = lines.filter(line => {
        const safeToString = (value) => {
          if (value === null || value === undefined) return '';
          return String(value).toLowerCase();
        };

        const searchableFields = {
          name: safeToString(line.name),
          phone: safeToString(line.phone),
          idNumber: safeToString(line.idNumber)
        };

        if (searchType === 'all') {
          return Object.values(searchableFields).some(field => 
            field.includes(term)
          );
        }
        return searchableFields[searchType]?.includes(term) || false;
      });

      // Filter by date range
      if (startDate || endDate) {
        customers = customers.filter(customer => {
          const itemDate = customer.dateCreated ? new Date(customer.dateCreated) : null;
          if (!itemDate) return false;
          
          if (startDate && endDate) {
            const start = new Date(startDate);
            const end = new Date(endDate);
            end.setHours(23, 59, 59, 999);
            return itemDate >= start && itemDate <= end;
          } else if (startDate) {
            const start = new Date(startDate);
            return itemDate >= start;
          } else if (endDate) {
            const end = new Date(endDate);
            end.setHours(23, 59, 59, 999);
            return itemDate <= end;
          }
          return true;
        });
      }

      setSearchResults(customers);
      setCustomerDetail(null);
      if (customers.length === 0 && searchTerm) {
        showToast('No customers found matching your filters', true);
      }
    } catch (error) {
      console.error('Search error:', error);
      showToast('Error searching customers. Please try again.', true);
    }
    setLoading(false);
  };

  const handleClearFilters = () => {
    setSearchTerm('');
    setSearchType('all');
    setStartDate('');
    setEndDate('');
    setSearchResults([]);
    setCustomerDetail(null);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const loadCustomerDetail = async (phone) => {
    setLoading(true);
    try {
      const [linesResult, tillsResult] = await Promise.all([
        apiCall('getLines'),
        apiCall('getTills')
      ]);

      const lines = linesResult.lines || [];
      const tills = tillsResult.tills || [];

      const normalizedSearchPhone = normalizePhone(phone);
      const customer = lines.find(l => normalizePhone(l.phone) === normalizedSearchPhone);

      if (customer) {
        const customerTills = tills.filter(t => normalizePhone(t.phone) === normalizedSearchPhone);
        setCustomerDetail({ customer, customerTills });
        // Scroll to detail view on mobile
        setTimeout(() => {
          const detailView = document.getElementById('customerDetailView');
          if (detailView) {
            detailView.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        }, 100);
      } else {
        setCustomerDetail(null);
        showToast('Customer not found', true);
      }
    } catch (error) {
      console.error('Error loading customer detail:', error);
      showToast('Error loading customer data', true);
    }
    setLoading(false);
  };

  const handleAddUnits = async (rowIndex, phone) => {
    const add = prompt('Enter number of units to add:');
    if (add && !isNaN(parseFloat(add)) && parseFloat(add) > 0) {
      const res = await apiCall('updateUnits', { rowIndex, addUnits: parseFloat(add) });
      if (res.success) {
        showToast(`✅ Added ${add} units successfully!`);
        loadCustomerDetail(phone);
      } else {
        showToast('Failed to add units', true);
      }
    }
  };

  return (
    <>
      <h3 className="section-title">
        <i className="fas fa-id-card"></i> Customer 360° View
        <span className="badge-count">{searchResults.length} customers</span>
      </h3>
      
      <div className="search-bar-advanced">
        <div className="search-row">
          <div className="search-input-group">
            <i className="fas fa-search search-icon"></i>
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder="Search by name, phone number, or ID..."
              className="search-input"
            />
          </div>
          <select 
            value={searchType}
            onChange={(e) => setSearchType(e.target.value)}
            className="search-select"
          >
            <option value="all">All Fields</option>
            <option value="name">Name</option>
            <option value="phone">Phone Number</option>
            <option value="idNumber">ID Number</option>
          </select>
        </div>
        
        <div className="date-row">
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> From</label>
            <input 
              type="date" 
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="date-group">
            <label><i className="fas fa-calendar-alt"></i> To</label>
            <input 
              type="date" 
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="date-input"
            />
          </div>
          <div className="action-group">
            <button className="btn-search-primary" onClick={handleSearch} disabled={loading}>
              <i className={`fas ${loading ? 'fa-spinner fa-pulse' : 'fa-search'}`}></i>
              {loading ? 'Searching...' : 'Search'}
            </button>
            <button className="btn-secondary" onClick={handleClearFilters}>
              <i className="fas fa-undo"></i> Clear
            </button>
          </div>
        </div>
      </div>

      {/* Search Results */}
      <div id="customerSearchResults">
        {loading && (
          <div className="loading">
            <i className="fas fa-spinner fa-pulse"></i> Searching...
          </div>
        )}
        {!loading && searchResults.length === 0 && searchTerm && (
          <div className="empty-state">
            <i className="fas fa-user-slash"></i>
            <br />No customers found matching your search
          </div>
        )}
        {!loading && searchResults.length === 0 && !searchTerm && (
          <div className="empty-state">
            <i className="fas fa-search"></i>
            <br />Search for a customer to see their 360° view
          </div>
        )}
        {!loading && searchResults.length > 0 && (
          <div style={{ marginBottom: '1.5rem' }}>
            <h4 style={{ marginBottom: '1rem', color: '#1e4a3b' }}>
              <i className="fas fa-users"></i> Search Results 
              <span style={{ fontSize: '0.9rem', color: '#5b6e69' }}>
                ({searchResults.length} customer{searchResults.length !== 1 ? 's' : ''} found)
              </span>
            </h4>
            <div className="table-wrapper">
              <table className="modern-table">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Phone</th>
                    <th>ID Number</th>
                    <th>Registered</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {searchResults.map((customer, index) => (
                    <tr key={index}>
                      <td><strong>{escapeHtml(customer.name)}</strong></td>
                      <td><i className="fas fa-phone"></i> {escapeHtml(customer.phone)}</td>
                      <td>{escapeHtml(customer.idNumber)}</td>
                      <td>{customer.dateCreated ? new Date(customer.dateCreated).toLocaleDateString() : '-'}</td>
                      <td>
                        <button 
                          className="action-btn" 
                          onClick={() => loadCustomerDetail(customer.phone)}
                        >
                          <i className="fas fa-eye"></i> View 360°
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Customer Detail View */}
      <div id="customerDetailView">
        {customerDetail && (
          <CustomerDetail 
            customer={customerDetail.customer}
            customerTills={customerDetail.customerTills}
            onAddUnits={handleAddUnits}
            onRefresh={() => loadCustomerDetail(customerDetail.customer.phone)}
          />
        )}
      </div>
    </>
  );
};

// CustomerDetail sub-component
const CustomerDetail = ({ customer, customerTills, onAddUnits, onRefresh }) => {
  const totalUnits = customerTills.reduce((sum, t) => sum + (t.units || 0), 0);
  const activeTills = customerTills.filter(t => t.status === 'active').length;

  return (
    <div style={{ marginTop: '2rem' }}>
      <div className="customer-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem', flexWrap: 'wrap' }}>
          <div className="customer-avatar">
            <i className="fas fa-user-circle"></i>
          </div>
          <div className="customer-info">
            <h2>{escapeHtml(customer.name)}</h2>
            <p><i className="fas fa-phone"></i> {escapeHtml(customer.phone)}</p>
            <p><i className="fas fa-id-card"></i> ID: {escapeHtml(customer.idNumber)}</p>
            <p><i className="fas fa-calendar"></i> DOB: {escapeHtml(customer.dob) || 'Not specified'}</p>
            <p><i className="fas fa-calendar-alt"></i> Registered: {customer.dateCreated ? new Date(customer.dateCreated).toLocaleDateString() : 'N/A'}</p>
          </div>
        </div>
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
          <div className="stats-badge">
            <div className="number">{customerTills.length}</div>
            <div className="label">Total Tills</div>
          </div>
          <div className="stats-badge">
            <div className="number">{activeTills}</div>
            <div className="label">Active Tills</div>
          </div>
          <div className="stats-badge">
            <div className="number">{totalUnits}</div>
            <div className="label">Total Units</div>
          </div>
        </div>
      </div>
      
      <div className="dashboard-grid">
        <div className="info-card">
          <h4><i className="fas fa-chart-line"></i> Performance Metrics</h4>
          <div className="info-row">
            <span className="info-label">Total Units Stocked:</span>
            <span className="info-value"><strong>{totalUnits}</strong> units</span>
          </div>
          <div className="info-row">
            <span className="info-label">Avg Units per Till:</span>
            <span className="info-value">
              {customerTills.length > 0 ? Math.round(totalUnits / customerTills.length) : 0} units
            </span>
          </div>
          <div className="info-row">
            <span className="info-label">Customer Since:</span>
            <span className="info-value">
              {customer.dateCreated ? new Date(customer.dateCreated).toLocaleDateString() : 'N/A'}
            </span>
          </div>
        </div>
        
        <div className="info-card">
          <h4><i className="fas fa-chart-pie"></i> Business Impact</h4>
          <div className="info-row">
            <span className="info-label">Revenue Generated:</span>
            <span className="info-value">KES {(totalUnits * 10).toLocaleString()}</span>
          </div>
          <div className="info-row">
            <span className="info-label">Commission Earned:</span>
            <span className="info-value">KES {(activeTills * 200).toLocaleString()}</span>
          </div>
        </div>
      </div>
      
      <h4 style={{ margin: '1.5rem 0 1rem', color: '#1e4a3b' }}>
        <i className="fas fa-cash-register"></i> Customer's Tills 
        <span style={{ fontSize: '0.8rem', fontWeight: 'normal' }}> ({customerTills.length} tills)</span>
      </h4>
      
      {customerTills.length > 0 ? (
        <div className="table-wrapper">
          <table className="modern-table">
            <thead>
              <tr>
                <th>Till Number</th>
                <th>Store</th>
                <th>Operator ID</th>
                <th>Units</th>
                <th>Status</th>
                <th>Date Created</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {customerTills.map((till, index) => (
                <tr key={index}>
                  <td><strong><span className="till-badge">{escapeHtml(till.tillNumber || '-')}</span></strong></td>
                  <td>{escapeHtml(till.storeNumber || '-')}</td>
                  <td><span className="operator-badge">{escapeHtml(till.operatorId || '-')}</span></td>
                  <td>
                    <span className={`units-display ${till.units < 50 && till.status === 'active' ? 'low-units' : ''}`}>
                      {till.units || 0} units
                      {till.units < 50 && till.status === 'active' && <i className="fas fa-exclamation-triangle low-units-icon"></i>}
                    </span>
                  </td>
                  <td>
                    {till.status === 'active' ? 
                      <span className="badge badge-success"><i className="fas fa-check-circle"></i> Active</span> : 
                      <span className="badge badge-danger"><i className="fas fa-times-circle"></i> Inactive</span>
                    }
                  </td>
                  <td>{till.dateCreated ? new Date(till.dateCreated).toLocaleDateString() : '-'}</td>
                  <td>
                    <button 
                      className="btn-add-units" 
                      onClick={() => onAddUnits(till.rowIndex, customer.phone)}
                      disabled={till.status !== 'active'}
                    >
                      <i className="fas fa-plus-circle"></i> Add Units
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="empty-state">
          <i className="fas fa-inbox"></i>
          <br />No tills registered for this customer
        </div>
      )}
      
      <div style={{ marginTop: '1.5rem', padding: '1rem', background: '#f8fbf9', borderRadius: '16px' }}>
        <h4 style={{ marginBottom: '1rem' }}><i className="fas fa-bolt"></i> Quick Actions</h4>
        <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
          <button 
            className="btn-secondary" 
            style={{ width: 'auto' }}
            onClick={() => {
              if (window.confirm(`Call ${customer.name} at ${customer.phone}?`)) {
                window.location.href = `tel:${customer.phone}`;
              }
            }}
          >
            <i className="fas fa-phone"></i> Contact Customer
          </button>
          <button 
            className="btn-secondary" 
            style={{ width: 'auto' }}
            onClick={() => {
              // Navigate to till registration with phone pre-filled
              const tillRegLink = document.querySelector('[data-page="TillReg"]');
              if (tillRegLink) {
                tillRegLink.click();
                // Set the phone in till registration after navigation
                setTimeout(() => {
                  const fetchPhoneInput = document.getElementById('fetchPhone');
                  if (fetchPhoneInput) {
                    fetchPhoneInput.value = customer.phone;
                    // Trigger the fetch
                    const fetchBtn = document.getElementById('fetchLineBtn');
                    if (fetchBtn) fetchBtn.click();
                  }
                }, 500);
              }
            }}
          >
            <i className="fas fa-cash-register"></i> Register New Till
          </button>
          <button 
            className="btn-secondary" 
            style={{ width: 'auto' }}
            onClick={onRefresh}
          >
            <i className="fas fa-sync-alt"></i> Refresh Data
          </button>
        </div>
      </div>
    </div>
  );
};

export default Customer360;
